def count_substrings(s):
    n, ans = len(s), 0
    def grow(l, r):
        nonlocal ans
        while l >= 0 and r < n and s[l] == s[r]:
            ans += 1; l -= 1; r += 1
    for i in range(n):
        grow(i, i)          # odd centers
        grow(i, i + 1)      # even gaps
    return ans
